void checkForDuplicateColors(GameInfo *game)
{
	if (game == 0)
		return;
	for (Int i = 7; i >= 0; --i)
	{
		GameSlot *slot = game->getSlot(i);
		if (slot != 0 && slot->isOccupied())
		{
			Int color = slot->m_color;
			if (color >= 0 && color < TheMultiplayerSettings->getNumColors())
			{
				slot->m_color = -1;
				if (!game->isColorTaken(color, -1))
					slot->m_color = color;
			}
		}
	}
}

