void GameLogic::destroyAllObjectsImmediate()
{
	m_unk0x164.clear();
	Object *nextObj;
	for (Object *obj = m_objList; obj; obj = nextObj)
	{
		nextObj = obj->getNextObject();
		destroyObject(obj);
	}
	processDestroyList();
	if (TheGameClient)
		TheGameClient->rva00239911();
}

