Bool GameLogic::findBuildableStatusOverride(const ThingTemplate *tmpl, BuildableStatus *status)
{
	if (tmpl)
	{
		BuildableOverrideMap::iterator found = m_thingTemplateBuildableOverrides.find(tmpl->getName());
		if (found != m_thingTemplateBuildableOverrides.end())
		{
			*status = found->second;
			return true;
		}
	}
	return false;
}

// FUNCTION: BFME2 0x00245F14 size=101 name=?addTOCEntry@GameLogic@@QAEXVAsciiString@@G@Z evidence=N:ledger tier=A
void GameLogic::addTOCEntry(AsciiString name, UnsignedShort id)
{
	ObjectTOCEntry tocEntry;
	tocEntry.name = name;
	tocEntry.id = id;
	m_objectTOC.push_back(tocEntry);
}

// FUNCTION: BFME2 0x00245F79 size=330 name=?xferObjectTOC@GameLogic@@QAEXPAVXfer@@@Z evidence=N:ledger tier=A
void GameLogic::xferObjectTOC(Xfer *xfer)
{
	xfer->Version1();

	m_objectTOC.clear();

	UnsignedInt tocCount = 0;
	if (xfer->IsStoring())
	{
		AsciiString templateName;

		for (Object *obj = m_objList; obj; obj = obj->getNextObject())
		{
			templateName = obj->getTemplate()->getName();
			if (findTOCEntryByName(templateName) != 0)
				continue;
			addTOCEntry(obj->getTemplate()->getName(), ++tocCount);
		}

		*xfer == tocCount;

		for (ObjectTOCList::iterator it = m_objectTOC.begin(); it != m_objectTOC.end(); ++it)
		{
			ObjectTOCEntry *tocEntry = &(*it);
			*xfer == tocEntry->name;
			*xfer == tocEntry->id;
		}
	}
	else
	{
		AsciiString templateName;
		UnsignedShort id;

		*xfer == tocCount;

		for (UnsignedInt i = 0; i < tocCount; ++i)
		{
			*xfer == templateName;
			*xfer == id;
			addTOCEntry(templateName, id);
		}
	}
}

